import{_ as e,o as i,c as a,ag as t}from"./chunks/framework.DPTJCqgd.js";const n="/deepseek-harness-desktop/assets/providers-models-page.eE-oU525.png",o="/deepseek-harness-desktop/assets/providers-custom-form.BNc3z5LC.png",E=JSON.parse('{"title":"Configure models","description":"","frontmatter":{"editSource":"docs/user/guide/providers.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/2847c75ea844b05f9d8adca865940856f1286c8c/docs/user/guide/providers.md"},"headers":[],"relativePath":"en/guide/providers.md","filePath":"en/guide/providers.md"}'),l={name:"en/guide/providers.md"};function h(p,s,d,r,k,c){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="configure-models" tabindex="-1">Configure models <a class="header-anchor" href="#configure-models" aria-label="Permalink to &quot;Configure models&quot;">​</a></h1><p>Open Harness Desktop following the <a href="./quickstart">getting-started guide</a>, or use an already running Harness Web UI. Model changes take effect on the next request without restarting the runtime.</p><h2 id="configure-deepseek" tabindex="-1">Configure DeepSeek <a class="header-anchor" href="#configure-deepseek" aria-label="Permalink to &quot;Configure DeepSeek&quot;">​</a></h2><p>Open <strong>Settings → Models</strong>. The DeepSeek card exposes one API-key field; enter the key and save it.</p><p><img src="'+n+'" alt="The Models page: the DeepSeek card, with Add provider and Add a custom provider below it"></p><p>Keys are write-only. The page receives a redacted descriptor after saving, never the literal secret. The key is stored in <code>$DSH_HOME/.credentials.yaml</code>, while settings retain only its credential reference.</p><h2 id="add-a-built-in-provider" tabindex="-1">Add a built-in provider <a class="header-anchor" href="#add-a-built-in-provider" aria-label="Permalink to &quot;Add a built-in provider&quot;">​</a></h2><p>Choose <strong>Add provider</strong> and pick a provider dsh ships with; the list shows provider ids such as <code>anthropic</code>, <code>openai</code>, <code>moonshotai</code> for Kimi, or <code>zai</code> for GLM. Enter its API key and save. The installed catalog supplies the endpoint, protocol, and model list.</p><p>Providers that sign in with OAuth, such as Codex, are not supported here yet.</p><h2 id="add-a-custom-provider" tabindex="-1">Add a custom provider <a class="header-anchor" href="#add-a-custom-provider" aria-label="Permalink to &quot;Add a custom provider&quot;">​</a></h2><p>Choose <strong>Add a custom provider</strong> for a company gateway, self-hosted server, or provider absent from the installed catalog. Supply a lowercase Provider ID, base URL, API protocol, credential, and at least one model. The <strong>API protocol</strong> must be the one your gateway speaks, and the form offers three: <code>openai-completions</code> for OpenAI Chat Completions, <code>openai-responses</code> for the OpenAI Responses API, and <code>anthropic-messages</code> for the Anthropic Messages API. A provider speaks one protocol, so a gateway that serves two needs two providers.</p><p><img src="'+o+`" alt="The custom provider form: Provider ID, display name, base URL, API protocol, and API key"></p><p>The Provider ID is permanent because requests, saved sessions, model defaults, and credential references use it. To rename a provider, add a new provider and delete the old one. The display name, base URL, protocol, credential, and models remain editable.</p><h3 id="discover-models" tabindex="-1">Discover models <a class="header-anchor" href="#discover-models" aria-label="Permalink to &quot;Discover models&quot;">​</a></h3><p>Under <strong>Model catalog</strong>, choose <strong>Fetch available models</strong> to ask the endpoint which models it serves. The request uses the base URL, protocol, and key currently in the form, or a saved provider&#39;s stored key, and the reply opens a searchable picker: search, tick the models you want, and choose <strong>Add selected</strong>. Nothing is stored until you save or create the provider.</p><p>Discovery reads the listing formats common gateways publish, but not every endpoint answers in one of them, so treat it as a convenience rather than a guarantee: when it fails or lists nothing, add the model ids by hand and they work just the same. A built-in provider is always answered from the installed catalog, even when its base URL points at a gateway, so fetch through a custom provider to see what the gateway really serves.</p><h2 id="select-a-model" tabindex="-1">Select a model <a class="header-anchor" href="#select-a-model" aria-label="Permalink to &quot;Select a model&quot;">​</a></h2><p>Configured providers appear in the model picker. Selecting a model also makes it the default for new sessions. A session that has already sent a request retains the model recorded in its own log.</p><p>If a saved default names a provider that was deleted, the composer displays <strong>Select model</strong> and blocks input until another model is selected.</p><h2 id="advanced-configuration" tabindex="-1">Advanced configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced configuration&quot;">​</a></h2><p>The generated <a href="./../reference/config-catalog">plugin configuration catalog</a> lists every supported field and default for every plugin; <a href="./../reference/config-catalog#deepseek-aidsh-llm-pi-ai"><code>dsh-llm-pi-ai</code></a> is the provider section this page configures. The <a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/packages/llm/llm-pi-ai/README.md" target="_blank" rel="noreferrer"><code>dsh-llm-pi-ai</code></a> and <a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/packages/llm/llm-deepseek/README.md" target="_blank" rel="noreferrer"><code>dsh-llm-deepseek</code></a> references own direct <code>settings.yaml</code> configuration, catalog resolution, reasoning controls, credentials, and adapter errors.</p><div class="tip custom-block"><p class="custom-block-title">The form is deliberately small</p><p>The Models page exposes only what a route needs to exist: the API key, display name, base URL, API protocol, and for each model its id, display name, context window, and max output tokens. Every other field — reasoning effort levels, image input, request-compatibility switches, headers, timeouts, retry policy — is set in <code>$DSH_HOME/settings.yaml</code>, the same document the page writes. Edit it directly, or, when the browser runs on the same machine as the server, open it with <strong>Open configuration file</strong> in the Settings header; the adapters re-read it on the next request, so nothing needs a restart. The subsections below cover the fields most gateways need.</p></div><h3 id="image-input" tabindex="-1">Image input <a class="header-anchor" href="#image-input" aria-label="Permalink to &quot;Image input&quot;">​</a></h3><p>A model you enter by hand is treated as text-only until it says otherwise, because nothing can ask an endpoint which modalities it accepts. Attaching an image to such a model is refused before it is sent, naming the model.</p><p>A vision model on a custom provider therefore needs one line. The form has no field for it; add <code>input</code> to the model in <code>$DSH_HOME/settings.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-pi-ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    my-gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKeyEnv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GATEWAY_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai-completions</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gateway.example/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">legacy-chat</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vision-preview</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>input</code> accepts <code>text</code> and <code>image</code>, and applies to that model alone, so one route can serve both kinds. Omitting it — or writing an empty list, which means the same thing — keeps whatever the installed catalog records for that model, and falls back to the route&#39;s <code>defaultInput</code> for a model the catalog does not describe.</p><p>If every model you entered by hand takes images, set the fallback once on the route instead of on each of them:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-pi-ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    vision-gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKeyEnv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GATEWAY_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai-completions</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://vision.example/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      defaultInput</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">first-model</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">second-model</span></span></code></pre></div><p><code>defaultInput</code> is a fallback, not an override, and defaults to <code>[text]</code>: on a built-in provider it answers only for models its catalog does not describe, so it never removes images from a catalog model that has them. Narrow one of those with that model&#39;s own <code>input</code>. A built-in provider has no <code>models</code> list to put it in, so write it under <code>modelOverrides</code>, keyed by model id:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-pi-ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    anthropic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      modelOverrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        claude-sonnet-4-5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Every list must name at least one modality except a model&#39;s own, where an empty list means the same as omitting it. An unknown modality is refused wherever it is written.</p><p>Both fields state a claim about your endpoint rather than checking it. A model that declares images its endpoint does not serve is not caught here; the provider rejects the request instead.</p><h3 id="reasoning-effort" tabindex="-1">Reasoning effort <a class="header-anchor" href="#reasoning-effort" aria-label="Permalink to &quot;Reasoning effort&quot;">​</a></h3><p>The model picker offers an <strong>Effort</strong> menu for a model that declares reasoning levels. A built-in provider&#39;s models inherit their levels from the installed catalog. A model you enter by hand declares none, so the Effort entry does not appear in the menu and the endpoint&#39;s own default decides whether the model thinks. Declare the levels with <code>reasoningEfforts</code> in <code>$DSH_HOME/settings.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-pi-ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    my-gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKeyEnv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GATEWAY_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai-completions</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gateway.example/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      reasoning</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-reasoner</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          reasoningEfforts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            high</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">max</span></span></code></pre></div><p>Each key is a level the menu offers, and its value is the spelling sent on the wire as <code>reasoning_effort</code>, so <code>max: xhigh</code> renames a level for a gateway with its own vocabulary. Only <code>off</code> may stay empty, because for most endpoints not thinking is the parameter&#39;s absence. The route&#39;s <code>reasoning</code> is the level used while a session has picked none; choosing an effort in the picker saves it, with the model, as the default for new sessions.</p><p>An <code>off</code> left empty sends nothing, which only stops a model that thinks on request; an <code>off</code> given a value sends that value as <code>reasoning_effort</code> instead. A model that thinks unless told not to — DeepSeek V4 behind an OpenAI-compatible gateway, for example — needs <code>compat.thinkingFormat: deepseek</code>, which makes <code>off</code> send <code>thinking: {type: disabled}</code> and every other level send <code>thinking: {type: enabled}</code> beside the effort:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-v4-pro</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          compat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            thinkingFormat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          reasoningEfforts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            high</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">max</span></span></code></pre></div><p>A built-in provider&#39;s model whose gateway does not reason loses its levels with <code>reasoningEfforts: false</code> under <code>modelOverrides</code>; selecting an effort for it is then refused as <code>UNSUPPORTED_REASONING_EFFORT</code>. DeepSeek&#39;s own route needs none of this: its models already offer <code>off</code>, <code>low</code>, <code>high</code>, and <code>max</code>, and <code>llm-deepseek.reasoningEffort</code> sets the default the picker starts from:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-deepseek</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  reasoningEffort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">max</span></span></code></pre></div><h3 id="request-compatibility" tabindex="-1">Request compatibility <a class="header-anchor" href="#request-compatibility" aria-label="Permalink to &quot;Request compatibility&quot;">​</a></h3><p>A gateway can hold a working key at a reachable address and still refuse every request. pi-ai decides the shape of a request — which role carries the system prompt, which field caps the output, how a thinking level travels — from the endpoint&#39;s URL, and an address it does not recognize is addressed as though it were OpenAI itself. Most OpenAI-compatible gateways refuse at least one thing OpenAI accepts.</p><p>Two account for most of it. A model that declares reasoning has its system prompt sent as <code>role: &quot;developer&quot;</code>, which many gateways reject outright, and the output cap is sent as <code>max_completion_tokens</code>, which a server that only knows <code>max_tokens</code> refuses. The form has no field for either; correct them on the route in <code>$DSH_HOME/settings.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm-pi-ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    my-gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKeyEnv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GATEWAY_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai-completions</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gateway.example/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      compat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        supportsDeveloperRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        maxTokensField</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">max_tokens</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-model</span></span></code></pre></div><p>A route&#39;s <code>compat</code> is the default for its models, and a model&#39;s own wins field by field, so one model can be corrected without restating the route:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-model</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-reasoner</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          compat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            thinkingFormat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek</span></span></code></pre></div><p>What neither sets keeps the installed catalog&#39;s value for that model, and what the catalog does not describe falls to pi-ai&#39;s detection. Give every switch you name a value: a key left empty (<code>supportsDeveloperRole:</code>) is refused rather than ignored, because an empty value would erase what the catalog knows while saying nothing in its place. A name no protocol accepts is refused too, and the message lists the ones that are available.</p><p>Each switch belongs to the protocols that declare it, so a switch valid on one <code>api</code> may be refused on another — the message names what that protocol does offer. Like <code>input</code> above, a switch states a claim about your endpoint rather than checking it: setting one your gateway does not actually need simply sends a different request.</p><p>Every switch, its accepted values, and the protocols that take it are listed under <code>PiAiCompatProfile</code> in the <a href="./../reference/config-catalog#deepseek-aidsh-llm-pi-ai">generated <code>dsh-llm-pi-ai</code> configuration reference</a> — which is derived from the source, so it cannot fall behind what the adapter accepts.</p><p><a id="provider-troubleshooting"></a></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong><code>MISSING_CREDENTIAL</code></strong> — Store the provider key through the Models page or supply the referenced environment variable.</li><li><strong><code>UNKNOWN_MODEL</code></strong> — Select a configured model or add the missing model to the custom provider.</li><li><strong>Fetching available models returns 401</strong> — Check the key. Model discovery supports OpenAI-compatible and Anthropic Messages model-listing endpoints; enter models manually when your endpoint does not support discovery.</li><li><strong>Fetching available models reports neither a <code>data</code> array nor a <code>models</code> object</strong> — The endpoint&#39;s listing is in a format discovery does not read. Enter the models by hand.</li><li><strong>The gateway refuses every request although the key and URL are right</strong> — Its request shape differs from OpenAI&#39;s. Start with <code>compat.supportsDeveloperRole: false</code> and <code>compat.maxTokensField: max_tokens</code> on the route.</li><li><strong>Only reasoning models fail</strong> — pi-ai sends their system prompt as the <code>developer</code> role, which the gateway rejects. Set <code>compat.supportsDeveloperRole: false</code>.</li><li><strong>The Effort menu does not appear for a model you entered by hand</strong> — It declares no levels. Add <code>reasoningEfforts</code> to the model in <code>settings.yaml</code>.</li><li><strong><code>off</code> does not stop a DeepSeek model from thinking</strong> — An empty <code>off</code> sends no reasoning field at all, and an endpoint that thinks by default keeps thinking. Set <code>compat.thinkingFormat: deepseek</code> on the model or the route.</li><li><strong>A compat switch is refused as having no value</strong> — A key written with nothing after the colon. Give it a value, or remove the key to keep the installed catalog&#39;s.</li><li><strong>An image is refused before sending</strong> — The model declares no image modality. Give a custom provider&#39;s model <code>input: [text, image]</code>; on DeepSeek&#39;s own route, select <code>deepseek-v4-flash-vision-exp</code>, the model that declares images.</li><li><strong>The provider rejects a request carrying an image</strong> — The model declares images its endpoint does not actually serve. Remove <code>image</code> from whichever list granted it — the model&#39;s <code>input</code>, or the route&#39;s <code>defaultInput</code> — then start a new session: the attached image stays in the session log, so the same request repeats until the session moves off it.</li></ul>`,53)])])}const y=e(l,[["render",h]]);export{E as __pageData,y as default};
